// Native oracle for the HF cache naming slice (S2), generated by tests/gen_s2.py.
// Includes the translation unit so the file-local helpers are callable; only
// string/path decisions are called, so no socket is opened and no file is read.
#include "hf-cache.cpp"

#include <cstdio>
#include <string>
#include <vector>
#include <filesystem>

namespace fs = std::filesystem;

// common.cpp:510, copied verbatim. It is the only external helper the mapping
// functions reach; it is a left-to-right replace loop, not a decision under
// test, and linking all of common.cpp would drag in httplib and the log queue.
void string_replace_all(std::string & s, const std::string & search, const std::string & replace) {
    if (search.empty()) {
        return;
    }
    std::string builder;
    builder.reserve(s.length());
    size_t pos = 0;
    size_t last_pos = 0;
    while ((pos = s.find(search, last_pos)) != std::string::npos) {
        builder.append(s, last_pos, pos - last_pos);
        builder.append(replace);
        last_pos = pos + search.length();
    }
    builder.append(s, last_pos, std::string::npos);
    s = std::move(builder);
}

static std::vector<std::string> split(const std::string & blob) {
    std::vector<std::string> out;
    size_t start = 0;
    for (size_t i = 0; i <= blob.size(); ++i) {
        if (i == blob.size() || blob[i] == '|') {
            out.push_back(blob.substr(start, i - start));
            start = i + 1;
        }
    }
    return out;
}

static void put(const std::string & s) {
    fwrite(s.data(), 1, s.size(), stdout);
}

