    // subpaths: containment plus the normalized join
    {
        auto v = split("a|a/b|a/../b|..|../..|../../../../..||.|./a|/abs|/|a/b/..|feature/x|...|a/./b|a//b|a/|a/./|x/..//|config.json|sub/dir/model.gguf|a/b/../../../..|.hidden|..hidden|a..b/c");
        const std::string base = "/cache/hub/models--u--m/snapshots/0123456789abcdef0123456789abcdef01234567";
        for (size_t i = 0; i < v.size(); ++i) {
            fs::path t = (fs::path(base) / v[i]).lexically_normal();
            printf("S%zu|%d|", i, (int) hf_cache::is_valid_subpath(base, v[i]));
            if (fs::path(v[i]).is_absolute()) {
                put("-");
            } else {
                put(t.generic_string());
            }
            printf("\n");
        }
    }

    // path assembly: the final snapshot path and the blobs redirect
    {
        struct C { const char * repo; const char * commit; const char * sub; const char * oid; int exists; };
        static const C cases[] = {
        { "user/model", "0123456789abcdef0123456789abcdef01234567", "model.gguf", "0123456789abcdef0123456789abcdef01234567", 0 },
        { "user/model", "0123456789abcdef0123456789abcdef01234567", "model.gguf", "0123456789abcdef0123456789abcdef01234567", 1 },
        { "user/model", "0123456789abcdef0123456789abcdef01234567", "model.gguf", "", 0 },
        { "u/m", "fedcba9876543210fedcba98765432100123456789abcdef0123456789abcdef", "dir/file.bin", "fedcba9876543210fedcba98765432100123456789abcdef0123456789abcdef", 0 },
        { "a/b", "0123456789abcdef0123456789abcdef01234567", "x", "", 0 },
        { "a/b", "0123456789abcdef0123456789abcdef01234567", "a/b/../c", "0123456789abcdef0123456789abcdef01234567", 1 },
        { "org-name/model_1.2", "0123456789abcdef0123456789abcdef01234567", "sub/weights.gguf", "0123456789abcdef0123456789abcdef01234567", 0 },
        { "a/b", "0123456789abcdef0123456789abcdef01234567", "", "", 0 }
    };
        for (size_t i = 0; i < sizeof(cases) / sizeof(cases[0]); ++i) {
            const std::string repo = cases[i].repo;
            const std::string oid = cases[i].oid;
            fs::path folder = hf_cache::repo_to_folder_name(repo);
            fs::path commit_path = fs::path("/cache/hub") / folder / "snapshots" / cases[i].commit;
            fs::path final_path = commit_path / cases[i].sub;
            fs::path local_path;
            int which;
            if (!oid.empty() && cases[i].exists == 0) {
                local_path = fs::path("/cache/hub") / folder / "blobs" / oid;
                which = 0;
            } else {
                local_path = final_path;
                which = 1;
            }
            printf("P%zu|%s|%s|%d\n", i, final_path.generic_string().c_str(),
                   local_path.generic_string().c_str(), which);
        }
    }

